class Solution:
    def canReach(self, members: List[int], follower: List[int], following: List[int], a: int, b: int) -> int:
        g = defaultdict(list)
        for u, v in zip(follower, following): g[u].append(v)
        seen = {a}; q = deque([a])
        while q:
            u = q.popleft()
            if u == b: return 1
            for v in g[u]:
                if v not in seen: seen.add(v); q.append(v)
        return 0

